html,
body {
  height: 100%;
  height: 100svh;
  width: 100%;
  overflow: hidden;
  font-size: 16px;
  padding: 0;
  margin: 0;
  font-family: system-ui, "SF Pro", "Segoe UI", "Almaden Sans", Roboto, Ubuntu, Helvetica, Arial;
  -webkit-font-smoothing: antialiased;
  color: #4a4a4a;
}

#root {
  width: 100%;
  height: 100%;
  position: fixed;
  top: 0;
  left: 0;
}

#zmmtg-root {
  width: 100%;
  height: 100%;
  position: fixed;
  top: 0;
  left: 0;
  background-color: black;
}

#cdn_path {
  display: none;
}

.display-none {
  display: none;
}

/*common*/
.showme {
  visibility: visible;
}

.hideme {
  visibility: hidden;
}

label {
  font-weight: normal;
}

.btn-sm {
  font-size: 12px;
  line-height: 1.5;
  border-radius: 3px;
}

.btn-default:hover {
  color: #333;
  background-color: #ebebeb;
  border-color: #adadad;
}

.btn-primary {
  background-color: #0e71eb;
  border-color: #0e71eb;
}

.btn-primary:hover {
  background-color: #2681f2;
  border-color: #2681f2;
}

a, button {
  outline: 2px solid transparent;
  outline-offset: 2px;
  -webkit-transition: 0.2s all ease-in;
  transition: 0.2s all ease-in;
}
a:focus, button:focus {
  outline: 2px solid #0E71EB;
  outline-offset: 1px;
}

a:hover {
  outline: 0 solid transparent;
}

/*************************header******************************/
#wc-header {
  height: 48px;
  width: 100%;
}

.meeting-tip {
  text-align: center;
  padding-top: 23px;
}

.sharing-tip {
  position: absolute;
  top: 64px;
  text-align: center;
  width: 100%;
}

.sharing-tip div {
  display: inline-block;
  font-size: 13px;
  line-height: 24px;
  color: #3a3c36;
  width: 270px;
  text-align: center;
  background-color: #4bc800;
  -webkit-box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.5);
          box-shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.5);
  border-radius: 40px;
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
  height: 24px;
  padding: 0 15px;
}

.sharing-tip span {
  opacity: 0.5;
  color: #1f4707;
}

.meeting-tip span {
  margin: 0 10px;
}

.meeting-tip span:last-child {
  max-width: 650px !important;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

#wc-container-left {
  -webkit-box-flex: 1;
      -ms-flex: 1;
          flex: 1;
  position: relative;
